import * as T from './vendor/three.js';
const read=async(url,type)=>{const r=await fetch(url);if(!r.ok)throw Error(`Could not load ${url}`);return new type(await r.arrayBuffer())};
export async function loadWorld(scene){
 const [meta,coarse,fine,buildings,roofData,wallData,map]=await Promise.all([fetch('./geodata.json').then(r=>r.json()),read('./terrain.bin',Int32Array),read('./terrain-fine.bin',Int32Array),fetch('./buildings.json').then(r=>r.json()),read('./building-roofs.bin',Float32Array),read('./building-walls.bin',Float32Array),fetch('./map.json').then(r=>r.json())]);
 const datum=meta.originElevation;
 function sample(a,g,x,z){let u=T.MathUtils.clamp((x-g.minX)/g.step,0,g.width-1.000001),v=T.MathUtils.clamp((z-g.minZ)/g.step,0,g.height-1.000001),i=Math.floor(u),j=Math.floor(v),du=u-i,dv=v-j,k=j*g.width+i;return(du+dv<=1?a[k]+du*(a[k+1]-a[k])+dv*(a[k+g.width]-a[k]):a[k+g.width+1]+(1-du)*(a[k+g.width]-a[k+g.width+1])+(1-dv)*(a[k+1]-a[k+g.width+1]))/100-datum}
 const coarseGrid={...meta.terrain,width:meta.terrain.size,height:meta.terrain.size};
 const coarseHeight=(x,z)=>sample(coarse,coarseGrid,x,z);
 function ground(x,z){let f=meta.fine;if(x<f.minX||z<f.minZ||x>f.minX+(f.width-1)*f.step||z>f.minZ+(f.height-1)*f.step)return coarseHeight(x,z);const edge=Math.min(x-f.minX,z-f.minZ,f.minX+(f.width-1)*f.step-x,f.minZ+(f.height-1)*f.step-z);return T.MathUtils.lerp(coarseHeight(x,z),sample(fine,f,x,z),Math.min(1,edge/20))}
 function terrainMesh(grid,step,skipCentre=false){const width=Math.round((grid.width-1)*grid.step/step)+1,height=Math.round((grid.height-1)*grid.step/step)+1;const positions=new Float32Array(width*height*3),colors=new Float32Array(width*height*3),indices=[];const col=new T.Color();for(let j=0;j<height;j++)for(let i=0;i<width;i++){let x=grid.minX+i*step,z=grid.minZ+j*step,y=ground(x,z),k=(j*width+i)*3;positions.set([x,y,z],k);const slope=Math.hypot(ground(x+4,z)-ground(x-4,z),ground(x,z+4)-ground(x,z-4))/8;col.set(slope>.4?'#526e48':y>140?'#638051':'#7f8d63');colors.set([col.r,col.g,col.b],k);if(i<width-1&&j<height-1){const f=meta.fine;if(skipCentre&&x>=f.minX&&z>=f.minZ&&x+step<=f.minX+(f.width-1)*f.step&&z+step<=f.minZ+(f.height-1)*f.step)continue;let a=j*width+i;indices.push(a,a+width,a+1,a+1,a+width,a+width+1)}}const geo=new T.BufferGeometry();geo.setAttribute('position',new T.BufferAttribute(positions,3));geo.setAttribute('color',new T.BufferAttribute(colors,3));geo.setIndex(indices);geo.computeVertexNormals();const mesh=new T.Mesh(geo,new T.MeshLambertMaterial({vertexColors:true}));scene.add(mesh)}
 terrainMesh(coarseGrid,20,true);terrainMesh(meta.fine,2);
 // Every vertex here comes from the surveyed footprint and DSM processing step.
 const wallGeo=new T.BufferGeometry();wallGeo.setAttribute('position',new T.BufferAttribute(wallData,3));wallGeo.computeVertexNormals();const uv=new Float32Array(wallData.length/3*2);for(let i=0,j=0;i<wallData.length;i+=3,j+=2){uv[j]=(wallData[i]+wallData[i+2])/8;uv[j+1]=wallData[i+1]/3.4}wallGeo.setAttribute('uv',new T.BufferAttribute(uv,2));
 const canvas=document.createElement('canvas');canvas.width=128;canvas.height=64;const c=canvas.getContext('2d');c.fillStyle='#b5b29e';c.fillRect(0,0,128,64);c.fillStyle='#6f827c';c.fillRect(15,17,38,31);c.fillRect(77,17,38,31);c.fillStyle='#bfc8b1';c.fillRect(18,19,32,3);c.fillRect(80,19,32,3);c.fillStyle='#d1cbb6';c.fillRect(33,17,2,31);c.fillRect(95,17,2,31);const texture=new T.CanvasTexture(canvas);texture.wrapS=texture.wrapT=T.RepeatWrapping;texture.magFilter=T.NearestFilter;texture.colorSpace=T.SRGBColorSpace;scene.add(new T.Mesh(wallGeo,new T.MeshLambertMaterial({map:texture,side:T.DoubleSide})));
 const roofGeo=new T.BufferGeometry();roofGeo.setAttribute('position',new T.BufferAttribute(roofData,3));roofGeo.computeVertexNormals();scene.add(new T.Mesh(roofGeo,new T.MeshLambertMaterial({color:'#727e77',side:T.DoubleSide,flatShading:true})));
 const roads=map.elements.map(el=>({p:el.geometry.map(p=>new T.Vector2(p.x,p.z)),name:el.tags.name||'',type:el.tags.highway,width:['primary','secondary','tertiary'].includes(el.tags.highway)?11:['footway','path','cycleway','steps'].includes(el.tags.highway)?1.8:el.tags.highway==='service'?4:7}));
 const strips={road:[],pavement:[],line:[]};
 function strip(a,b,width,offset,key){const dx=b.x-a.x,dz=b.y-a.y,len=Math.hypot(dx,dz);if(len<.001)return;const nx=dz/len,nz=-dx/len,n=Math.max(1,Math.ceil(len/1.5)),across=Math.max(1,Math.ceil(width/1.5));for(let k=0;k<n;k++){let a1=a.clone().lerp(b,k/n),b1=a.clone().lerp(b,(k+1)/n);for(let j=0;j<across;j++){let l=-width/2+j*width/across,r=-width/2+(j+1)*width/across;const p=[[a1.x+nx*l,a1.y+nz*l],[a1.x+nx*r,a1.y+nz*r],[b1.x+nx*r,b1.y+nz*r],[b1.x+nx*l,b1.y+nz*l]];for(const i of [0,2,1,0,3,2]){const [x,z]=p[i];strips[key].push(x,ground(x,z)+offset,z)}}}}

 for(const r of roads)for(let i=1;i<r.p.length;i++){const a=r.p[i-1],b=r.p[i];strip(a,b,r.width+2.5,.07,'pavement');strip(a,b,r.width,.11,'road');if(r.width>6){const len=a.distanceTo(b);for(let j=3;j<len;j+=14)strip(a.clone().lerp(b,j/len),a.clone().lerp(b,Math.min((j+4)/len,1)),.12,.145,'line')}}
 for(const [key,color]of [['pavement','#aaa899'],['road','#696d68'],['line','#ded5ac']]){const g=new T.BufferGeometry();g.setAttribute('position',new T.Float32BufferAttribute(strips[key],3));g.computeVertexNormals();scene.add(new T.Mesh(g,new T.MeshLambertMaterial({color,side:T.DoubleSide,polygonOffset:true,polygonOffsetFactor:key==='line'?-4:key==='road'?-3:-2,polygonOffsetUnits:-2})))}
 function nearest(x,z){let best=Infinity,name='Wainuiomata';for(const r of roads){for(let i=1;i<r.p.length;i++){const a=r.p[i-1],b=r.p[i],vx=b.x-a.x,vz=b.y-a.y,len=vx*vx+vz*vz;if(!len)continue;const t=T.MathUtils.clamp(((x-a.x)*vx+(z-a.y)*vz)/len,0,1),d=Math.hypot(a.x+t*vx-x,a.y+t*vz-z);if(d<best){best=d;name=r.name||'Wainuiomata'}}}return{d:best,name}}
 const cells=new Map();for(const b of buildings){let r=b.rings[0];b.minX=Math.min(...r.map(p=>p[0]));b.maxX=Math.max(...r.map(p=>p[0]));b.minZ=Math.min(...r.map(p=>p[1]));b.maxZ=Math.max(...r.map(p=>p[1]));for(let i=Math.floor((b.minX-1)/25);i<=Math.floor((b.maxX+1)/25);i++)for(let j=Math.floor((b.minZ-1)/25);j<=Math.floor((b.maxZ+1)/25);j++){let key=i+','+j;if(!cells.has(key))cells.set(key,[]);cells.get(key).push(b)}}
 function inside(r,x,z){let found=false;for(let i=0,j=r.length-1;i<r.length;j=i++){const [xi,zi]=r[i],[xj,zj]=r[j];if((zi>z)!==(zj>z)&&x<(xj-xi)*(z-zi)/(zj-zi)+xi)found=!found}return found}
 function free(x,z){for(const b of cells.get(Math.floor(x/25)+','+Math.floor(z/25))||[]){if(inside(b.rings[0],x,z)&&!b.rings.slice(1).some(r=>inside(r,x,z)))return false;for(const r of b.rings)for(let i=1;i<r.length;i++){const a=r[i-1],c=r[i],dx=c[0]-a[0],dz=c[1]-a[1],t=T.MathUtils.clamp(((x-a[0])*dx+(z-a[1])*dz)/(dx*dx+dz*dz||1),0,1);if(Math.hypot(x-a[0]-t*dx,z-a[1]-t*dz)<.35)return false}}return true}
 // Decorative vegetation only; all terrain and building geometry remains measured.
 let seed=91;const rand=()=>{seed=(seed*16807)%2147483647;return(seed-1)/2147483646};const trunkGeo=new T.CylinderGeometry(.25,.4,4,5),leafGeo=new T.ConeGeometry(3.3,8,5),trunk=new T.InstancedMesh(trunkGeo,new T.MeshLambertMaterial({color:'#716b51'}),240),leaves=new T.InstancedMesh(leafGeo,new T.MeshLambertMaterial({color:'#486746'}),240);let n=0;const dummy=new T.Object3D();for(let i=0;i<900&&n<240;i++){const x=(rand()-.5)*2600,z=(rand()-.5)*2600;if(nearest(x,z).d<24||!free(x,z))continue;const y=ground(x,z);dummy.position.set(x,y+2,z);dummy.updateMatrix();trunk.setMatrixAt(n,dummy.matrix);dummy.position.y=y+7;dummy.updateMatrix();leaves.setMatrixAt(n++,dummy.matrix)}trunk.count=leaves.count=n;scene.add(trunk,leaves);
 return{meta,ground,roads,buildings,nearest,free};
}
